$ErrorActionPreference = 'Stop'
Set-Location (Split-Path $PSScriptRoot -Parent)
if (-not (Test-Path -LiteralPath '.env')) {
  function New-Secret {
    $bytes = New-Object byte[] 24
    [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($bytes)
    return ([BitConverter]::ToString($bytes)).Replace('-','').ToLower()
  }
  $content = @'
# Local development configuration generated by scripts/setup.ps1.
MYSQL_ROOT_PASSWORD=CHANGE_ME_ROOT_PASSWORD
MYSQL_PASSWORD=CHANGE_ME_DATABASE_PASSWORD
MYSQL_DATABASE=meditrack
MYSQL_USER=meditrack
# Encode special characters in the username/password when forming this URL.
DATABASE_URL=mysql://meditrack:CHANGE_ME_DATABASE_PASSWORD@127.0.0.1:3307/meditrack
QDRANT_URL=http://127.0.0.1:6333
QDRANT_API_KEY=CHANGE_ME_VECTOR_KEY
EMBEDDING_URL=http://127.0.0.1:8000
APP_ORIGIN=http://localhost:3000
COOKIE_SECURE=false
DEMO_ADMIN_PASSWORD=CHANGE_ME_ADMIN_PASSWORD
DEMO_STAFF_PASSWORD=CHANGE_ME_STAFF_PASSWORD

# Generated automatically by scripts/apply-update.ts. Do not copy placeholder passwords.
# MYSQL_AUTH_PASSWORD, MYSQL_ADMIN_PASSWORD, MYSQL_STAFF_PASSWORD
# AUTH_DATABASE_URL, ADMIN_DATABASE_URL, STAFF_DATABASE_URL
MYSQL_HOST_PORT=3307
'@
  $content = $content.Replace('CHANGE_ME_ROOT_PASSWORD',(New-Secret)).Replace('CHANGE_ME_DATABASE_PASSWORD',(New-Secret)).Replace('CHANGE_ME_VECTOR_KEY',(New-Secret)).Replace('CHANGE_ME_ADMIN_PASSWORD',(New-Secret)).Replace('CHANGE_ME_STAFF_PASSWORD',(New-Secret))
  Set-Content -LiteralPath '.env' -Value $content -Encoding utf8
  Write-Host 'Created .env with unique secrets. Demo passwords are in that file.'
}
npm.cmd ci
if ($LASTEXITCODE -ne 0) { throw 'npm ci failed' }
docker compose up -d --build mysql qdrant embedding
if ($LASTEXITCODE -ne 0) { throw 'Docker startup failed. Check the error above for a port conflict or Docker engine issue.' }
Write-Host 'Waiting for databases and embedding model; first download may take several minutes.'
for ($attempt=0;$attempt -lt 180;$attempt++) {
  # A refused connection during MySQL initialization is expected: retry it instead of stopping.
  $probePreference = $ErrorActionPreference
  try {
    $ErrorActionPreference = 'Continue'
    'SELECT COUNT(*) FROM medicines;' | docker compose exec -T mysql sh -c 'export MYSQL_PWD; MYSQL_PWD=$MYSQL_PASSWORD; exec mysql --protocol=TCP --host=127.0.0.1 --port=3306 --user=meditrack --database=meditrack --batch --skip-column-names' 2>$null | Out-Null
    $databaseReady = $LASTEXITCODE -eq 0
  } finally {
    $ErrorActionPreference = $probePreference
  }
  try { $modelReady = (Invoke-RestMethod 'http://127.0.0.1:8000/health').ready } catch { $modelReady = $false }
  if ($databaseReady -and $modelReady) { break }
  Start-Sleep -Seconds 5
}
if (-not $databaseReady) { throw 'MySQL did not become ready. Run: docker compose logs --tail 60 mysql' }
if (-not $modelReady) { throw 'Embedding model is still unavailable. Run: docker compose logs --tail 60 embedding' }
node --env-file=.env --import tsx scripts/apply-update.ts
if ($LASTEXITCODE -ne 0) { throw 'Role and query migration failed' }
node --env-file=.env --import tsx scripts/seed.ts --with-vectors
if ($LASTEXITCODE -ne 0) { throw 'Seeding failed' }
Write-Host 'Ready. Run npm run dev, then open http://localhost:3000.'
